export function welcome(s){return `<div class="welcome"><section class="welcome-hero"><div class="welcome-copy"><span class="eyebrow">SYNK PULSE · CLIENT ROOM</span><h1>같은 장면을 상상하고,<span>함께 완성해요.</span></h1><p class="lead">좋아하는 분위기를 모으고, 광고의 방향을 고르고, 완성되어 가는 영상을 보며 이야기를 나누세요.</p><form class="entry-card" data-form="invite"><h2 class="entry-title">내 프로젝트 열기</h2>${field('담당자에게 받은 초대 링크','invite','','password',{required:true,max:3000,placeholder:'초대 링크를 붙여 넣어 주세요',help:'연결하면 이 프로젝트의 자료와 대화만 볼 수 있어요.'})}${submit('프로젝트로 들어가기 →')}<p class="form-note">가입이나 비밀번호 없이 열려요. 받은 링크를 눌러도 바로 이 화면이 열려요. 열리지 않으면 담당자에게 새 링크를 요청해 주세요.</p></form><dl class="welcome-steps"><div><dt>01</dt><dd><strong>원하는 느낌을 함께</strong>참고 이미지와 링크로 취향을 전하고 콘셉트를 비교해요.</dd></div><div><dt>02</dt><dd><strong>장면을 먼저 확인</strong>광고의 순서와 문구를 보고 제작 전에 방향을 맞춰요.</dd></div><div><dt>03</dt><dd><strong>영상에서 바로 이야기</strong>멈춘 장면에 의견을 남기고 수정된 시안을 확인해요.</dd></div></dl></div><div class="welcome-art poster tall len-2" data-word="펄스"><span class="poster-label">01 / SYNK PULSE</span><span class="led-chip">초대받은 고객 전용</span><img class="cut" src="./assets/stage/hero-camera.webp" alt="펠트로 만든 영화 카메라" width="691" height="760"></div></section><section class="demo-entry"><div><span class="eyebrow">TRY A PROJECT</span><h2>고객이 되어 광고 한 편을 완성해 보세요.</h2><p>모루 커피의 취향 선택부터 영상 의견과 최종 승인까지.</p><small>로그인 없이 · 실제 의뢰 아님 · 이 기기에 체험 저장</small></div><a class="button soft" href="?demo=coffee">예시 프로젝트 체험하기 →</a></section><div class="entry-footer"><p class="small">앱 설치 없이 휴대폰과 컴퓨터에서 이용할 수 있어요.</p>${btn('연결 다시 확인','retry','','quiet small-button')}</div></div>`;}
export function login(){return `<section class="login-wrap"><div class="login-copy"><span class="eyebrow">PULSE / CREATOR</span><h1>함께 만들 준비가<span>여기서 시작돼요.</span></h1><p class="muted">기존 SYNK 제작자 계정으로 연결해 주세요.</p></div><div class="login-forms"><section class="panel-card"><h3>SYNK ID로 시작하기</h3><p>기존 워크스페이스에서 SYNK ID로 로그인한 뒤 이 화면으로 돌아오세요.</p><div class="button-row"><a class="button primary" href="/?tab=workroom&amp;section=clients" target="_blank" rel="noopener noreferrer">SYNK ID 로그인 열기 ↗</a>${btn('로그인 확인','check-login')}</div></section><form class="form-panel" data-form="login">${field('이메일 또는 기존 메신저 아이디','email','','text',{required:true,max:254})}${field('비밀번호','password','','password',{required:true,max:500})}${submit('제작자 로그인')}<p class="form-note">아이디·비밀번호 로그인은 기존에 발급된 제작자 계정에서 이용할 수 있어요. 고객 초대 링크는 고객 화면에서 열어 주세요.</p><a class="text-button" href="./">고객 화면으로 돌아가기</a></form></div></section>`;}
export function picker(s){return `<section class="project-picker">${pageIntro('CREATOR WORKSPACE','어떤 광고를 함께 만들까요?','고객과 공유할 방향, 장면, 영상 자료를 프로젝트별로 준비하세요.',s.workspace?.canWrite?btn('새 프로젝트','new-project','','primary'):'')}<div class="demo-entry is-compact"><div><span class="eyebrow">CLIENT EXPERIENCE</span><h3>고객은 어떤 화면을 보게 될까요?</h3><p>예시 광고로 취향 선택부터 최종 승인까지 직접 체험해 보세요.</p></div><a class="button soft" href="?demo=coffee" target="_blank" rel="noopener noreferrer">고객 체험 열기 ↗</a></div><div class="project-list">${(s.workspace?.projects||[]).map(p=>`<button type="button" class="project-tile" data-action="open-project" data-id="${esc(p.id)}"><span class="tag berry">${esc(stages[p.stage]||p.stage)}</span><strong>${esc(p.title)}</strong><span class="small">${esc(p.customerName)} · 담당 ${esc(p.ownerName||'확인 중')}</span><span class="small">${esc(p.nextStep||'다음 확인 사항을 정해 주세요.')}</span></button>`).join('')}</div>${!(s.workspace?.projects||[]).length?'<div class="empty-note"><h3>첫 프로젝트를 준비해 주세요.</h3><p>프로젝트를 만든 뒤 자료를 올리고 고객 초대 링크를 전달할 수 있어요.</p></div>':''}${s.newProject?`<form class="form-panel project-create" data-form="new-project"><h3>새 프로젝트</h3>${field('프로젝트 이름','title','','text',{required:true,max:160,placeholder:'예: 여름 신제품 30초 광고'})}${field('고객 이름 또는 회사','customerName','','text',{required:true,max:100})}${field('무엇을 함께 만들까요?','summary','','textarea',{placeholder:'이번 광고의 목적과 전달할 내용을 적어 주세요.'})}<div class="button-row">${submit('프로젝트 만들기')}${btn('취소','cancel-new')}</div></form>`:''}</section>`;}
export function nextDecision(p,canPrepareFinal=false){const s=studio(p),latest=(p.versions||[]).filter(v=>v.kind==='preview').at(-1),finals=(p.versions||[]).filter(v=>v.kind==='final'),currentFinal=latest?.approvedAt&&finals.some(v=>v.approvedPreviewId===latest.id);if(currentFinal&&p.stage==='delivered'){if(p.closeout?.deliveryKey&&p.closeout.approvedPreviewId===latest.id&&p.closeout.receipt?.confirmedAt)return {title:'수령 확인을 마쳤어요',text:'필요할 때 최종 파일과 사용 안내, 함께 남긴 기록을 다시 볼 수 있어요.',tab:'history',button:'납품 파일·기록 다시 보기'};return {title:'완성된 파일이 도착했어요',text:'최종 파일과 사용 안내를 확인해 주세요.',tab:'history',button:'납품 파일 확인'};}const approval=previewApprovalState(p);if(latest&&!latest.approvedAt&&!(s.strategy?.request&&Number(s.strategy.request.strategyRevision)===Number(s.strategy.revision)&&Number(s.strategy.confirmation?.strategyRevision)!==Number(s.strategy.revision))&&approval.waitingFor==='team')return {title:'수정 의견을 확인하고 있어요',text:approval.reason,tab:'review',button:'영상과 의견 보기'};const strategyRequested=s.strategy?.request&&Number(s.strategy.request.strategyRevision)===Number(s.strategy.revision);if(latest&&!latest.approvedAt&&!strategyRequested)return {title:'새 시안을 함께 확인해요',text:p.nextStep||`${latest.label}을 보고 의견을 남겨 주세요.`,tab:'review',button:'영상 확인하기'};const strategyDecision=strategyNext(p);if(strategyDecision)return strategyDecision;if(latest&&!latest.approvedAt)return {title:'새 시안을 함께 확인해요',text:p.nextStep||`${latest.label}을 보고 의견을 남겨 주세요.`,tab:'review',button:'영상 확인하기'};if(p.kickoff?.enabled&&p.kickoff.status==='waiting')return {title:'제작 시작 전 준비를 확인해요',text:'필요한 자료와 아직 정하지 않은 내용을 확인해 주세요.',tab:'strategy',button:'준비 자료 확인'};if(latest?.approvedAt&&!currentFinal)return canPrepareFinal?{title:'승인한 시안으로 납품을 준비해요',text:'최종 파일과 사용 안내를 등록한 뒤 납품 규격에 연결해 주세요.',tab:'review',button:'최종 납품 준비'}:{title:'시안 승인을 마쳤어요',text:'최종 파일을 준비하고 있어요. 준비가 끝나면 사용 안내와 함께 보내 드려요.',tab:'review',button:'승인한 시안 확인'};if(s.scenes?.length)return {title:'광고의 흐름을 먼저 맞춰요',text:p.nextStep||'각 장면의 이미지와 문구를 확인해 주세요.',tab:'storyboard',button:'장면 확인하기'};if(s.concepts?.length&&(!s.selectedConcept||!s.selectedConcept.current))return {title:'마음에 가까운 방향을 골라 주세요',text:p.nextStep||'제안한 콘셉트를 비교하고 원하는 방향을 알려 주세요.',tab:'concepts',button:'콘셉트 비교하기'};if(s.selectedConcept?.current&&!s.scenes?.length&&!latest&&!finals.length)return {title:'선택한 콘셉트로 장면을 준비하고 있어요',text:'함께 고른 방향을 바탕으로 광고의 흐름과 각 장면을 구체화하고 있어요.',tab:'concepts',button:'선택한 방향 확인'};return {title:'원하는 광고의 시작점을 함께',text:p.nextStep||'참고자료와 꼭 담을 내용을 전해 주세요.',tab:'direction',button:'방향 정리하기'};}
// 단계마다 끝났는지·볼 것이 있는지. 여정 막대와 포스터 상태 칩이 같은 값을 쓴다.
const current=(record,revision)=>!!record&&Number(revision)>0&&Number(record.strategyRevision??record.revision)===Number(revision)&&record.current!==false;
function stageStatus(p,key){
  const st=studio(p),strategy=st.strategy||{},versions=p.versions||[],latest=versions.filter(v=>v.kind==='preview').at(-1),finals=versions.filter(v=>v.kind==='final'),scenes=st.scenes||[];
  const prefs=Object.values(st.preferences||{}).some(v=>String(v||'').trim());
  const sceneDone=scene=>(st.sceneReviews||[]).filter(r=>r.sceneId===scene.id&&r.current).at(-1)?.status==='confirmed';
  const map={
    strategy:{done:current(strategy.confirmation,strategy.revision),has:Number(strategy.revision)>0,doneLabel:'확인 완료'},
    direction:{done:prefs||(st.references||[]).length>0||(st.previews?.sampleChoices||[]).length>0,has:true,doneLabel:'공유 완료'},
    concepts:{done:!!st.selectedConcept?.current,has:(st.concepts||[]).length>0,doneLabel:'선택 완료'},
    storyboard:{done:scenes.length>0&&scenes.every(sceneDone),has:scenes.length>0,doneLabel:'확인 완료'},
    review:{done:!!latest?.approvedAt,has:versions.length>0,doneLabel:'승인 완료'},
    history:{done:!!p.closeout?.receipt,has:finals.length>0,doneLabel:'수령 완료'},
    manage:{done:false,has:true,doneLabel:''}
  };
  return map[key]||map.manage;
}
// 「지금 할 일」의 차례: nextDecision·strategyNext 제목으로 고객 차례·제작팀 차례·끝을 나눈다.
const TEAM_TURN=new Set(['제작 설계를 함께 다듬고 있어요','승인한 시안으로 납품을 준비해요','시안 승인을 마쳤어요','선택한 콘셉트로 장면을 준비하고 있어요']);
function turnOf(s,next){
  if(s.demo)return 'customer';
  if(next.title==='수령 확인을 마쳤어요')return 'done';
  if(TEAM_TURN.has(next.title))return 'team';
  const p=s.project,latest=(p.versions||[]).filter(v=>v.kind==='preview').at(-1);if(next.tab==='review'&&previewApprovalState(p,{demo:s.demo}).waitingFor==='team')return 'team';
  if(next.tab==='review'&&latest&&!latest.approvedAt&&(p.messages||[]).some(m=>m.author==='customer'&&m.action==='feedback'&&!m.resolved&&m.versionId===latest.id))return 'team';
  return 'customer';
}
const turnLabel=(s,turn)=>turn==='done'?'모두 끝났어요':turn==='team'?(s.mode==='staff'?'우리 차례':'제작팀 차례'):(s.mode==='staff'?'고객 차례':'내 차례');
function stageState(s,key,next,turn){const status=stageStatus(s.project,key);if(key==='manage')return {state:'idle',label:'제작자 전용'};if(key===next.tab&&(!status.done||s.demo))return turn==='team'?{state:'team',label:s.mode==='staff'?'우리 차례':'제작팀이 준비 중'}:{state:'now',label:s.mode==='staff'?'고객과 확인할 일':'지금 할 일'};if(status.done)return {state:'done',label:status.doneLabel};return status.has?{state:'open',label:'둘러보기'}:{state:'wait',label:'준비 중'};}
// 단계 머리: 왼쪽은 두 줄 큰 제목·설명·「지금 할 일」, 오른쪽은 그 단계의 베리 포스터(펠트 물건 + 큰 한글).
function stageHero(s,key,next,turn,nowBlock){
  const info=STAGE[key]||STAGE.strategy,state=stageState(s,key,next,turn),len=[...info.word].length,total=s.mode==='staff'?'07':'06';
  return `<header class="section-intro stage-hero"><div class="stage-copy"><span class="eyebrow">${esc(info.no)} · ${esc(info.en)}</span><h2>${esc(info.title[0])}<span>${esc(info.title[1])}</span></h2><p class="stage-lead">${keepDots(esc(info.text))}</p>${nowBlock}</div><div class="poster stage-poster len-${len}${info.art?'':' no-art'}" data-word="${esc(info.word)}" aria-hidden="true"><span class="poster-label">STEP ${esc(info.no==='↗'?'—':info.no)} / ${total}</span><span class="led-chip is-${state.state}">${esc(state.label)}</span>${info.art?`<img class="cut" src="./assets/stage/${info.art}.webp" alt="" width="${info.w}" height="${info.h}" decoding="async">`:''}</div></header>`;
}
function journey(s,next,turn){
  const items=[...tabs,...(s.mode==='staff'?[['manage','↗','프로젝트 관리']]:[])];
  return `<nav class="journey" aria-label="프로젝트 단계">${items.map(([key,no,label])=>{const state=stageState(s,key,next,turn);return `<button type="button" data-action="tab" data-tab="${key}" aria-current="${s.tab===key?'page':'false'}" class="journey-step is-${state.state}"><span class="journey-no">${no}</span><span class="journey-label">${label}</span><span class="journey-state">${esc(state.label)}</span></button>`;}).join('')}</nav>`;
}
export function projectView(s){
  const p=s.project,next=s.demo?{title:s.demoGuide.title,text:s.demoGuide.description,tab:s.demoGuide.tab,button:'체험 단계 열기'}:nextDecision(p,s.mode==='staff'&&s.canEdit),here=s.tab===next.tab,turn=turnOf(s,next),nextStage=STAGE[next.tab]||STAGE.strategy,nextName=tabs.find(t=>t[0]===next.tab)?.[2]||'';
  const body=({strategy:strategyView,direction:directionView,concepts:conceptView,storyboard:storyboardView,review:reviewView,history:historyView,manage:manageView}[s.tab]||strategyView)(s);
  return `${s.demo?demoGuide(s):''}<div class="project-shell${s.demo?' is-demo':''}" data-mode="${esc(s.mode)}"><header class="project-head"><div class="project-identity"><span class="eyebrow">${s.mode==='staff'?'PULSE · CREATOR STUDIO':'PULSE · YOUR PROJECT'}</span><h1 class="project-title">${esc(p.title)}</h1><p class="project-sub">${esc(p.customerName||'')}&nbsp;· 담당 ${esc(p.ownerName||'확인 중')}</p></div><dl class="project-meta"><div><dt>전달 예정</dt><dd>${p.dueDate?`<time datetime="${esc(p.dueDate)}">${esc(day(p.dueDate))}</time>`:'함께 협의 중'}</dd></div><div><dt>현재 진행</dt><dd><span class="stage-dot stage-${esc(p.stage)}" aria-hidden="true"></span>${esc(stages[p.stage]||p.stage)}</dd></div><div class="meta-refresh">${btn('최신 내용 불러오기','refresh','title="최신 내용 불러오기"','quiet small-button refresh-button')}</div></dl></header>${journey(s,next,turn)}${s.error?`<div class="inline-alert" role="alert"><strong>${s.conflict?'요청을 진행하지 못했어요.':'저장하지 못했어요.'}</strong><div>${esc(s.error)}</div>${s.conflict?btn('최신 내용 불러오기 · 작성 내용 유지','refresh','','small-button'):''}</div>`:''}<section class="tab-panel" data-current-tab="${esc(s.tab)}" data-here="${here}">${stageHero(s,s.tab,next,turn,`<section class="next-decision"><div class="next-copy turn-${turn}"><span class="next-label"><span class="turn-chip is-${turn}">${esc(turnLabel(s,turn))}</span><span class="next-where">${esc(nextStage.no)} · ${esc(nextName)}</span></span><h3>${esc(next.title)}</h3><p>${esc(next.text)}</p></div>${btn(next.button,'tab',`data-tab="${next.tab}"${here?' data-scroll="content"':''}`,turn==='customer'?'primary':'soft')}</section>`)}${turn==='done'&&s.tab==='history'?'':confirmationScope(s)}${s.mode==='staff'?`<p class="staff-note">제작자 화면 · ${s.canEdit?'준비 중인 자료는 제작자만 보고, 고객 공개로 저장한 자료는 고객 화면에 보여요.':'이 프로젝트는 열람만 할 수 있어요.'}</p>`:''}${scheduleView(s)}<div class="stage-content" data-stage-content>${s.tab==='strategy'?changesView(s)+kickoffView(s):''}${body}${s.tab==='strategy'&&!s.demo?deliverablesView(s):''}${s.tab==='direction'&&!s.demo?samplesPanel(s):''}${s.tab==='history'&&!s.demo?deliverablesView(s,{readOnly:s.mode!=='staff'}):''}</div></section></div>`;
}
function directionView(s){const st=studio(s.project),p=st.preferences||{},editable=s.mode!=='staff'||s.canEdit;return `<div class="two-columns direction-layout"><form class="panel-card" data-form="preferences"><fieldset ${!editable?'disabled':''}><div class="card-head"><span class="card-no">01</span><h3>광고의 시작점</h3></div><div class="field-grid">${field('브랜드·제품','brand',p.brand||'','text',{max:300,placeholder:'무엇을 소개할까요?'})}${field('주로 볼 사람','audience',p.audience||'','text',{max:600,placeholder:'예: 첫 자취를 시작한 20대'})}</div>${field('광고를 보고 무엇이 달라지면 좋을까요?','goal',p.goal||'','textarea',{placeholder:'예: 새로운 제품이 나왔다는 것을 알리고, 출시 페이지로 방문하도록'})}${field('원하는 분위기','mood',p.mood||'','text',{max:1000,placeholder:'이미지나 영상의 어떤 느낌을 원하나요?'})}<div class="mood-options" aria-label="분위기 표현 추가">${['자연스러운','감각적인','따뜻한','유쾌한','힘 있는','차분한'].map(m=>`<button type="button" data-action="mood" data-value="${m}" aria-pressed="${(p.mood||'').includes(m)}">${m}</button>`).join('')}</div>${field('꼭 담을 내용','mustHave',p.mustHave||'','textarea',{placeholder:'제품 특징, 로고, 핵심 문구, 화면에 보여야 할 정보'})}${field('피하고 싶은 것','avoid',p.avoid||'','textarea',{placeholder:'예: 과한 효과, 어려운 용어, 어두운 화면'})}${field('기타·메모','notes',p.notes||'','textarea')}<div class="button-row">${editable?submit('이 방향을 함께 보기'):''}</div><p class="form-note">${s.demo?'저장한 선택과 메모는 이 브라우저의 체험에만 남아요.':'저장하면 담당자와 같은 내용을 볼 수 있어요.'}</p></fieldset></form><div class="stack"><section class="panel-card"><div class="card-head"><span class="card-no">02</span><h3>느낌을 보여주는 자료</h3></div><p class="small">이미지 또는 참고 링크를 남겨 주세요. 좋아하는 요소와 피할 요소를 구분할 수 있어요.</p>${references(st.references||[],editable,s.mode)}${editable?`<details class="form-panel"><summary>참고자료 추가</summary><form data-form="reference">${field('자료 이름','label','','text',{required:true,max:160,placeholder:'예: 이 영상의 빠른 시작'})}${field('참고 링크','url','','url',{max:2000,placeholder:'https://…'})}${s.demo?'<p class="small">체험에서는 준비된 이미지를 고르거나 참고 링크를 남겨 보세요. 파일 업로드는 실제 프로젝트에서 사용할 수 있어요.</p>':field('또는 참고 이미지','file','','file',{help:'PNG·JPEG, 최대 100MiB'})}<label class="field">이미 올린 이미지<select name="assetId"><option value="">선택하지 않음</option>${(st.assets||[]).filter(isImage).map(a=>`<option value="${esc(a.id)}">${esc(a.fileName)}</option>`).join('')}</select></label><label class="field">이 자료를 보여주는 이유<select name="preference"><option value="like">이런 느낌이 좋아요</option><option value="avoid">이런 느낌은 피하고 싶어요</option><option value="neutral">참고만 해 주세요</option></select></label>${field('어떤 부분인가요?','reason','','textarea',{placeholder:'색감, 분위기, 장면의 움직임처럼 원하는 부분을 알려 주세요.'})}${submit('참고자료 공유')}</form></details>`:''}</section><section class="panel-card scope-card"><div class="card-head"><span class="card-no">03</span><h3>함께 정한 범위</h3></div><p class="detail-copy">${esc(s.project.summary||'내용을 협의한 뒤 여기에 정리해요.')}</p><p class="detail-copy">${esc(s.project.terms||'제작 범위·수정 조건은 담당자와 함께 정해요.')}</p></section></div></div>`;}
function references(items,editable,mode){return items.length?`<div class="reference-grid">${items.map(r=>`<article class="reference-card is-${esc(r.preference||'neutral')}">${r.media?.mimeType?.startsWith('image/')?visual({media:r.media,title:r.label},'reference-media'):`<div class="reference-file">${r.media?'첨부 파일':'참고 링크'} ↗</div>`}<div class="reference-copy"><div class="tags"><span class="tag ${r.preference==='avoid'?'warn':r.preference==='like'?'berry':''}">${{like:'좋은 방향',avoid:'피할 방향',neutral:'참고'}[r.preference]||'참고'}</span></div><h4>${esc(r.label)}</h4>${r.reason?`<p>${esc(r.reason)}</p>`:''}${safeUrl(r.url)?`<a href="${esc(safeUrl(r.url))}" target="_blank" rel="noopener noreferrer">자료 열기 ↗</a>`:''}${r.media&&!r.media.mimeType?.startsWith('image/')?`<a href="${esc(safeUrl(r.media.url,{media:true}))}" download>첨부 받기</a>`:''}<div class="button-row">${editable?btn('이 자료에 대한 생각','reference-opinion',targetAttrs(r.id),'quiet small-button'):''}${editable&&(mode==='staff'||r.author==='customer')?btn('자료 지우기','remove-reference',targetAttrs(r.id),'quiet small-button'):''}</div></div></article>`).join('')}</div>`:'<p class="empty-note">아직 공유한 참고자료가 없어요.</p>';}
function conceptView(s){const st=studio(s.project),picked=st.selectedConcept,chosen=(st.concepts||[]).find(c=>c.id===picked?.conceptId);return `${tools(s.mode==='staff'&&s.canEdit?btn('콘셉트 준비하기','edit-concept','','primary'):'')}${picked?`<div class="selection-note ${picked.current?'is-current':'is-stale'}"><span class="selection-mark" aria-hidden="true"></span><div><strong>${esc(chosen?.title||'선택한 콘셉트')}${picked.current?' · 선택한 방향':' · 새 수정 내용 확인 필요'}</strong><p>${esc(picked.text||'이 방향으로 장면을 구체화해요.')}</p><p class="small">${esc(picked.authorName)} · ${esc(stamp(picked.at))}</p></div></div>`:''}<div class="concept-grid">${(st.concepts||[]).map((c,i)=>`<article class="concept-card ${picked?.conceptId===c.id&&picked.current?'is-selected':''}" id="concept-${esc(c.id)}">${visual(c)}<div class="concept-copy"><div class="tags"><span class="tag mono-tag">CONCEPT ${String(i+1).padStart(2,'0')} · v${esc(c.revision)}</span>${c.visibility==='internal'?'<span class="tag warn">제작자만 보기</span>':''}${picked?.conceptId===c.id&&picked.current?'<span class="tag green">선택한 방향</span>':''}</div><h3>${esc(c.title)}</h3>${c.tagline?`<p class="tagline">${esc(c.tagline)}</p>`:''}<p class="detail-copy">${esc(c.description)}</p><div class="button-row">${s.mode==='staff'?(s.canEdit?btn('콘셉트 수정','edit-concept',targetAttrs(c.id)):''):btn(picked?.conceptId===c.id&&picked.current?'선택 내용 남기기':'이 방향 선택','choose-concept',`${targetAttrs(c.id)} ${!imageSource(c)?'disabled title="이미지가 준비된 뒤 선택할 수 있어요"':''}`,'primary')}${btn('의견 남기기','comment',`data-target="concept" ${targetAttrs(c.id)}`,'quiet')}</div>${comments(st.comments||[],'concept',c.id,s.notificationCommentId)}</div></article>`).join('')}</div>${!st.concepts?.length?'<div class="empty-note"><h3>원하는 방향에 맞춰 콘셉트를 준비하고 있어요.</h3><p>이미지와 한 줄 메시지가 준비되면 여기서 나란히 비교할 수 있어요.</p></div>':''}${s.editor?.type==='concept'?editorForm(s,'concept'):''}`;}
function storyboardView(s){const st=studio(s.project),scenes=st.scenes||[],total=scenes.reduce((sum,c)=>sum+(Number(c.duration)||0),0),done=c=>(st.sceneReviews||[]).filter(r=>r.sceneId===c.id&&r.current).at(-1)?.status==='confirmed',checked=scenes.filter(done).length;return `${tools(s.mode==='staff'&&s.canEdit?btn('장면 추가','edit-scene','','primary'):'')}${st.strategy?.revision?`<details class="scene-strategy-summary"><summary>장면으로 이어갈 제작 설계 보기</summary>${strategySummary(s.project,{compact:true})}</details>`:''}${!s.demo?animaticPanel(s):''}${sceneDurationNote(s.project)}${sceneRequestsSummary(s)}${scenes.length?`<div class="scene-count"><span class="scene-progress"><strong>${checked}</strong> / ${scenes.length} 장면 확인</span><span class="scene-meter" aria-hidden="true">${scenes.map(c=>`<i class="${done(c)?'on':''}"></i>`).join('')}</span>${total?`<span class="tag">예상 길이 ${total}초</span>`:''}</div>`:''}<div class="scene-list">${scenes.map((c,i)=>{const reviews=(st.sceneReviews||[]).filter(r=>r.sceneId===c.id),last=reviews.filter(r=>r.current).at(-1);return `<article class="scene-card${last?.status==='confirmed'?' is-confirmed':''}" id="scene-${esc(c.id)}"><div class="scene-main">${visual(c,'scene-image')}<div class="scene-copy"><div class="scene-kicker"><span class="scene-number">SCENE ${String(i+1).padStart(2,'0')}</span><span class="tag">${Number(c.duration)||0}초 · v${esc(c.revision)}</span>${c.visibility==='internal'?'<span class="tag warn">제작자만 보기</span>':''}</div><h3>${esc(c.title)}</h3>${sceneStrategyContext(s.project,c)}<p class="detail-copy">${esc(c.description)}</p><dl><div><dt>전달할 말</dt><dd>${esc(c.narration||'없음')}</dd></div><div><dt>화면 문구</dt><dd>${esc(c.screenText||'없음')}</dd></div></dl></div></div><div class="scene-actions"><p>${last?`<span class="tag ${last.status==='confirmed'?'green':'warn'}">${{confirmed:'확인했어요',changes:'수정 의견 있음',comment:'의견 있음'}[last.status]}</span>`:'이 장면의 의견을 기다리고 있어요.'}</p><div class="button-row">${s.mode==='staff'?(s.canEdit?`${btn('수정','edit-scene',targetAttrs(c.id))}${i?btn('앞으로','move-scene',`${targetAttrs(c.id)} data-direction="-1"`):''}${i<scenes.length-1?btn('뒤로','move-scene',`${targetAttrs(c.id)} data-direction="1"`):''}`:''):`${btn((s.project.sceneRequests?.items||[]).some(r=>r.sceneId===c.id&&r.status==='waiting_customer'&&r.resultRevision===c.revision)?'수정된 장면 v'+c.revision+' 확인':'장면 확인했어요','confirm-scene',targetAttrs(c.id)+` data-revision="${esc(c.revision)}" data-project-revision="${esc(s.project.revision)}"`)}${btn('수정·참고 의견','review-scene',targetAttrs(c.id),'primary')}`}${s.mode==='staff'?btn('답변 남기기','comment',`data-target="scene" ${targetAttrs(c.id)}`,'quiet'):''}</div></div>${sceneRequestView(s,c)}${reviews.length?`<div class="scene-feedback">${reviews.filter(r=>!(s.project.sceneRequests?.items||[]).some(item=>item.id===r.id)).slice(-3).map(r=>`<p class="small"><strong>${esc(r.authorName)}</strong> · ${esc(stamp(r.at))} · v${esc(r.sceneRevision)}${!r.current?' 이전 장면':''}<br>${esc(r.text||'장면의 내용과 표현을 확인했어요.')}</p>`).join('')}</div>`:''}${(st.comments||[]).some(m=>m.targetType==='scene'&&m.targetId===c.id)?`<div class="scene-feedback">${comments(st.comments,'scene',c.id,s.notificationCommentId)}</div>`:''}</article>`;}).join('')}</div>${!scenes.length?'<div class="empty-note"><h3>선택한 방향이 장면으로 이어집니다.</h3><p>담당자가 콘티를 준비하면 광고의 순서와 메시지를 함께 확인할 수 있어요.</p></div>':''}${s.editor?.type==='scene'?editorForm(s,'scene'):''}`;}
function editorForm(s,type){const st=studio(s.project),item=(type==='concept'?st.concepts:st.scenes)?.find(c=>c.id===s.editor.id)||{};return `<form class="form-panel section-gap" id="creative-editor" data-form="${type}" data-id="${esc(item.id||'')}"><h3>${type==='concept'?'콘셉트':'장면'} ${item.id?'수정':'준비'}</h3>${field('이름','title',item.title||'','text',{required:true,max:160})}${field(type==='concept'?'어떤 아이디어인가요?':'화면에서 어떤 일이 일어나나요?','description',item.description||'','textarea')}${type==='concept'?field('한 줄 메시지','tagline',item.tagline||'','text',{max:300}):`${field('전달할 말·내레이션','narration',item.narration||'','textarea')}${field('화면 문구','screenText',item.screenText||'','textarea')}${field('장면 길이 (초)','duration',item.duration||3,'number',{required:true,max:8})}${sceneStrategyFields(s.project,item)}`}${assetFields(st,item)}${visibility(item.visibility)}<div class="button-row">${submit('저장하기')}${btn('닫기','close-editor')}</div><p class="form-note">새 버전으로 수정되면 고객은 바뀐 내용에 대해 다시 선택·확인할 수 있어요.</p></form>`;}
export function mediaView(v,{compare=false}={}){const url=safeUrl(v?.media?.url,{media:true});if(url&&v.media.mimeType?.startsWith('video/'))return `<video ${compare?'':'id="review-video"'} controls playsinline preload="metadata" src="${esc(url)}" data-version="${esc(v.id)}" aria-label="${esc(v.label)}"></video>`;if(url&&v.media.mimeType?.startsWith('image/'))return `<img src="${esc(url)}" alt="${esc(v.label)}">`;if(url)return `<div class="empty-visual"><div><p>${esc(v.media.fileName||v.label||'전달 파일')}</p><a class="button" href="${esc(url)}" download>파일 받기</a><p class="small">내려받은 파일과 사용 안내를 함께 확인해 주세요.</p></div></div>`;const external=safeUrl(v?.url);return `<div class="empty-visual"><div><p>${external?'링크로 전달된 자료예요.':'재생할 파일이 아직 준비되지 않았어요.'}</p>${external?`<a class="button" href="${esc(external)}" target="_blank" rel="noopener noreferrer">자료 열기 ↗</a>`:''}<p class="small">앱에서 바로 확인할 영상은 담당자가 파일로 올릴 수 있어요.</p></div></div>`;}
// 의견 시점 타임라인: 이 버전에 시간이 붙은 의견(초안·보낸 의견·대화)을 점으로. 누르면 그 장면으로(기존 seek). 위치는 영상 길이를 안 뒤 app.mjs가 놓는다.
function reviewTimeline(p,current,messages){if(!current?.media?.mimeType?.startsWith('video/'))return '';const rounds=p.studio?.feedbackRounds||{},marks=[];
  for(const d of rounds.drafts||[])if(d.versionId===current.id)for(const i of d.items||[])if(Number.isFinite(i.seconds))marks.push({t:i.seconds,text:i.text,kind:'draft',label:'초안'});
  for(const r of rounds.rounds||[])if(r.versionId===current.id)for(const i of r.items||[])if(Number.isFinite(i.seconds))marks.push({t:i.seconds,text:i.text,kind:i.resolved?'done':'sent',label:r.number+'차'});
  for(const m of messages)if(m.versionId===current.id&&Number.isFinite(m.seconds))marks.push({t:m.seconds,text:m.text,kind:m.resolved?'done':'sent',label:m.authorName||'의견'});
  if(!marks.length)return '';marks.sort((a,b)=>a.t-b.t);
  const draftsOnly=marks.every(m=>m.kind==='draft');
  return `<div class="review-timeline" data-timeline aria-label="${draftsOnly?'의견 초안이 달린 장면':'의견이 달린 장면'}"><span class="timeline-label">${draftsOnly?'초안':'의견'} <b>${marks.length}</b></span><div class="timeline-track"><i class="timeline-head" aria-hidden="true"></i>${marks.map(m=>`<button type="button" class="timeline-mark is-${m.kind}" data-action="seek" data-version="${esc(current.id)}" data-seconds="${m.t}" title="${esc(clock(m.t)+' · '+m.label+' · '+String(m.text||'').slice(0,60))}" aria-label="${esc(clock(m.t)+' '+m.label+' 의견 장면 보기')}"><span>${esc(clock(m.t))}</span></button>`).join('')}</div></div>`;}
function reviewConversationForm(s,latest,current,latestActive){return `<form class="review-form" data-form="feedback" id="review-feedback">${s.mode!=='staff'&&s.feedbackDraftVersion&&s.feedbackDraftVersion!==latest?.id?`<div class="inline-alert"><strong>이 글은 이전 시안에 작성한 의견이에요.</strong><p>새 시안으로 자동으로 옮기지 않아요. 최신 영상을 보고 글을 옮겨 쓸 수 있어요. 영상 시간은 다시 지정해 주세요.</p>${btn('이 글을 최신 시안에 옮겨 쓰기','move-feedback-draft','','small-button')}</div>`:''}<h3>${s.mode==='staff'?'고객에게 답변':s.demo?'이 장면에 의견 남기기':'후속 문의'}</h3><p class="small">${s.mode==='staff'?'고객의 문의에 답변을 남겨 주세요.':s.demo?'영상에서 바꾸고 싶은 부분을 알려 주세요.':'일정이나 전달 파일에 관해 궁금한 점을 남겨 주세요. 영상 수정 의견은 위에서 모아 보내 주세요.'}</p>${s.mode!=='staff'?(!s.demo||!latestActive||latest?.approvedAt?'<input type="hidden" name="action" value="support">':`<label class="field">의견 종류<select name="action"><option value="feedback">이 시안 수정 의견</option><option value="support">후속 문의</option></select></label>`):''}${field('내용','text','','textarea',{required:true,max:3000,placeholder:s.mode==='staff'?'고객에게 전할 답변을 적어 주세요.':s.demo?'어떤 부분이 어떻게 바뀌면 좋을까요?':'일정이나 전달 파일에 관해 궁금한 점을 적어 주세요.'})}${s.mode!=='staff'&&s.demo?`<div class="time-chip"><label for="comment-seconds" class="small">연결할 시간 (초)</label><input id="comment-seconds" type="number" name="seconds" inputmode="decimal" min="0" max="86400" step="0.1" aria-label="영상 시간 초">${current.media?.mimeType?.startsWith('video/')&&latestActive?btn('지금 장면 넣기','use-time','','small-button'):''}</div>`:''}${s.mode!=='staff'||s.canEdit?`<button type="submit" class="button primary" data-mutate ${s.mode!=='staff'&&s.feedbackDraftVersion&&s.feedbackDraftVersion!==latest?.id&&s.feedbackDraftAction!=='support'?'disabled':''}>${s.mode==='staff'?'고객에게 답변 보내기':s.demo?'이 의견 보내기':'문의 보내기'}</button>`:''}<p class="form-note">${s.demo?'이 기기의 체험 기록에만 저장돼요. 실제 담당자에게 전송하지 않아요.':'보내기를 누르면 담당자와 같은 기록을 볼 수 있어요.'}</p></form>`;}
function reviewView(s){const p=s.project,approval=previewApprovalState(p,{demo:s.demo}),versions=p.versions||[],previews=versions.filter(v=>v.kind==='preview'),latest=previews.at(-1),current=versions.find(v=>v.id===s.versionId)||latest||versions.at(-1),latestActive=current?.id===latest?.id,pending=latest?(p.messages||[]).filter(m=>m.author==='customer'&&m.action==='feedback'&&!m.resolved&&m.versionId===latest.id):[],messages=(p.messages||[]).filter(m=>s.mode==='staff'||!(p.studio?.feedbackRounds?.rounds||[]).some(r=>r.items?.some(i=>i.messageId===m.id))).filter(m=>m.versionId===current?.id||m.action==='support'||m.author==='staff'||(s.mode==='staff'&&m.author==='customer'&&!m.resolved)),previous=previews.length>1?previews.at(-2):null,draftCount=s.mode==='customer'?(p.studio?.feedbackRounds?.drafts||[]).filter(d=>d.current&&d.versionId===latest?.id).reduce((n,d)=>n+(d.items?.length||0),0):0;return `${tools(s.mode==='staff'&&s.canEdit?btn('시안·최종본 올리기','show-version','','primary'):'')}${current?`${!latestActive&&latest&&current.kind==='preview'&&!s.demo?`<div class="new-version-note"><div><strong>새 시안이 도착해 있어요.</strong><p>보던 영상과 쓰던 의견은 그대로 있어요.</p></div>${btn('최신 시안 확인','latest-version','','small-button')}</div>`:''}<div class="video-layout"><div class="review-media"><header class="video-heading"><div><span class="tag ${current.approvedAt?'green':'berry'}">${current.kind==='final'?'최종 전달':current.approvedAt?'승인한 시안':latestActive?'최신 시안':'이전 시안'}</span><h3>${esc(current.label)}</h3></div><label class="field version-field">버전<select data-action="version" aria-label="확인할 버전">${versions.slice().reverse().map(v=>`<option value="${esc(v.id)}" ${v.id===current.id?'selected':''}>${esc(v.label)}</option>`).join('')}</select></label></header><div class="video-frame">${mediaView(current)}</div>${reviewTimeline(p,current,messages)}<div class="review-toolbar">${s.mode!=='staff'?`<div class="review-quick-actions" aria-label="영상 확인 바로가기">${current.media?.mimeType?.startsWith('video/')&&latestActive&&!latest?.approvedAt?btn('이 장면에 의견',s.demo?'use-time':'round-use-time','data-focus-comment="true"','soft'):''}${latestActive&&latest&&!latest.approvedAt?btn('승인 확인','review-approval'):''}</div>`:''}<div class="button-row">${safeUrl(current.media?.url,{media:true})?`<a class="button small-button download" href="${esc(safeUrl(current.media.url,{media:true}))}" download>파일 받기</a>`:''}${previous?btn(s.compare?'비교 닫기':'이전 시안과 비교','compare','','quiet small-button'):''}</div></div><p id="video-error" class="inline-alert" hidden>파일을 재생하지 못했어요. 연결을 확인하거나 담당자에게 파일 상태를 확인해 주세요.</p><p class="video-note"><span class="note-label">제작팀 메모</span>${esc(current.guide||'내용과 표현을 확인해 주세요.')}</p>${s.compare&&previous&&latest?`<div class="compare-grid"><div><h4>${esc(previous.label)}</h4>${mediaView(previous,{compare:true})}</div><div><h4>${esc(latest.label)}</h4>${mediaView(latest,{compare:true})}</div></div>`:''}</div><aside class="review-actions">${!s.demo?feedbackRoundsPanel(s):''}${reviewConversationForm(s,latest,current,latestActive)}${s.mode!=='staff'&&latest?`<section class="approval-card${latest.approvedAt?' is-approved':''}" id="review-approval" tabindex="-1"><span class="eyebrow">VERSION APPROVAL</span><h3>${latest.approvedAt?'시안 승인을 마쳤어요':'이 시안을 기준으로 만들까요?'}</h3><p>${latest.approvedAt?esc(`${latest.label} · ${stamp(latest.approvedAt)}`):!approval.canApprove?esc(approval.reason):draftCount?`모은 의견 초안 ${draftCount}개가 있어요. 아래에서 먼저 보내거나 비운 뒤 승인할 수 있어요.`:esc(`${latest.label}의 내용과 표현을 확인한 뒤 최종 제작 진행에 동의할 수 있어요.`)}</p>${!latestActive&&!latest.approvedAt?'<p class="small">이전 버전을 보고 있어요. 위 버전 목록에서 최신 시안을 선택한 뒤 승인해 주세요.</p>':''}${!latest.approvedAt?btn('이 시안 최종 승인','approve',`${targetAttrs(latest.id)} ${!approval.canApprove||!latestActive||draftCount?'disabled':''}`,'primary'):''}</section>`:''}</aside><section class="review-comments"><h3>후속 문의와 답변${messages.length?`<span class="count">${messages.length}</span>`:''}</h3>${versionComments(messages,s)}${comments(p.studio?.comments||[],'project',null,s.notificationCommentId)}</section></div>`:`<div class="empty-note"><h3>제작한 시안이 여기에 도착해요.</h3><p>파일이 준비되면 앱에서 바로 재생하고 장면에 의견을 남길 수 있어요.</p></div>${reviewConversationForm(s,latest,current,latestActive)}<section class="review-comments"><h3>후속 문의와 답변</h3>${versionComments(messages,s)}${comments(p.studio?.comments||[],'project',null,s.notificationCommentId)}</section>`}${s.showVersion&&s.canEdit?versionForm():''}`;}
function versionForm(){return `<form class="form-panel section-gap" id="version-form" data-form="version"><h3>시안·최종본 전달</h3>${field('버전 이름','label','','text',{required:true,max:120,placeholder:'예: 30초 광고 · 시안 v1'})}<label class="field">종류<select name="kind"><option value="preview">고객 확인용 시안</option><option value="final">최종 납품 파일</option></select></label><label class="field">영상 또는 이미지 파일<input type="file" name="file" accept="video/mp4,video/webm,image/png,image/jpeg"><small>MP4·WebM·PNG·JPEG, 최대 100MiB. 파일로 올리면 고객이 앱 안에서 확인할 수 있어요.</small></label>${field('또는 전달할 자료 링크','url','','url',{max:2000,placeholder:'https://…'})}${field('확인할 내용·최종본 사용 안내','guide','','textarea',{max:1000,placeholder:'이번에 바뀐 내용 또는 납품 파일의 규격·사용 안내'})}<p class="small">최신 시안의 고객 승인을 마친 뒤 최종 납품 파일을 등록할 수 있어요.</p><div class="button-row">${submit('고객에게 전달하기')}${btn('닫기','hide-version')}</div></form>`;}
function workflowActions(message,s){
  if(s.mode!=='staff'||message.author!=='customer'||message.action==='approve')return '';
  const item=(s.workflow||[]).find(row=>row.messageId===message.id&&row.projectId===s.project.id);
  if(!item)return message.resolved?'<span class="small">처리 완료</span>':'';
  const latest=s.project.versions.filter(v=>v.kind==='preview'&&v.id!==message.versionId&&!v.approvedAt).at(-1);
  return `<div class="workflow-actions"><p class="small">${esc(item.statusLabel)}${item.note?` · ${esc(item.note)}`:''}</p>${(item.actions||[]).map(a=>a.action==='submit_review'?`<details><summary>${esc(a.label)}</summary><form data-form="workflow" data-message-id="${esc(message.id)}"><input type="hidden" name="action" value="submit_review"><label class="field">이 요청을 반영한 최신 시안<select name="versionId" required><option value="">수정본 선택</option>${latest?`<option value="${esc(latest.id)}">${esc(latest.label)}</option>`:''}</select></label>${!latest?'<p class="small">수정본을 먼저 등록한 뒤 이 요청에 연결해 주세요.</p>':''}${field('내부 검토 메모','note','','textarea')}<p class="small">검토 담당자가 지정된 경우 내부 검토를 먼저 거칩니다.</p>${submit(a.label)}</form></details>`:a.action==='request_changes'?`<details><summary>내부 수정 요청</summary><form data-form="workflow" data-message-id="${esc(message.id)}"><input type="hidden" name="action" value="request_changes">${field('수정할 내용','note','','textarea',{required:true})}${submit('수정 요청 보내기')}</form></details>`:btn(a.label,'workflow',`${targetAttrs(message.id)} data-workflow="${esc(a.action)}"`,'quiet small-button')).join('')}</div>`;
}
function versionComments(items,s){return items.length?`<div class="comment-list">${items.slice().reverse().map(m=>`<article class="comment" data-author="${esc(m.author||'')}" data-message-id="${esc(m.id)}" tabindex="-1"><div class="comment-top"><strong>${esc(m.authorName)}</strong><time>${esc(stamp(m.at))}</time></div><div class="tags"><span class="tag ${m.action==='approve'?'green':''}">${{feedback:'수정 의견',support:'문의',approve:'시안 승인'}[m.action]||'답변'}</span>${m.resolved?'<span class="tag green">처리됨</span>':''}</div><p>${esc(m.text)}</p><div class="button-row">${Number.isFinite(m.seconds)?btn(clock(m.seconds)+' 장면 보기','seek',`data-version="${esc(m.versionId||'')}" data-seconds="${m.seconds}"`,'quiet'):''}${workflowActions(m,s)}</div></article>`).join('')}</div>`:'<p class="empty-note">아직 문의나 답변이 없어요.</p>';}
function comments(items,type,id,focusId=null){const all=items.filter(m=>m.targetType===type&&m.targetId===id),rows=type==='project'?all:all.filter((m,i)=>i>=all.length-4||m.id===focusId);return rows.length?`<div class="comment-list">${rows.map(m=>`<article class="comment" data-message-id="${esc(m.id)}" tabindex="-1"><div class="comment-top"><strong>${esc(m.authorName)}</strong><time>${esc(stamp(m.at))}</time></div><p>${esc(m.text)}</p>${type==='project'?'':`<span class="small">v${esc(m.targetRevision||1)}에 남긴 의견</span>`}</article>`).join('')}</div>`:'';}
export function deliveryReceiptView(s){const p=s.project,c=p.closeout;if(!c?.deliveryKey)return '';const confirmed=!!c.receipt;return `${confirmed?`<section class="delivery-receipt panel-card section-gap is-confirmed" aria-label="납품 수령 확인"><span class="receipt-mark" aria-hidden="true"></span><div class="receipt-head"><p class="receipt-line"><strong>수령 확인 완료</strong> · <time datetime="${esc(c.receipt.confirmedAt)}">${esc(stamp(c.receipt.confirmedAt))}</time></p><p class="small">이후에도 이곳에서 자료를 받을 수 있어요. 후속 문의는 05 영상 확인에서 남겨 주세요.</p></div><ul class="receipt-list">${c.files.map(file=>`<li>${esc(file.label)}</li>`).join('')}</ul></section>`:`<section class="delivery-receipt panel-card section-gap" aria-label="납품 수령 확인"><div class="receipt-head"><div class="tags"><span class="tag ${confirmed?'green':'berry'}">${confirmed?'수령 확인 완료':'수령 확인 대기'}</span></div><h3>${confirmed?'파일과 안내를 확인했어요.':'전달 파일을 확인해 주세요'}</h3><p>${confirmed?esc(stamp(c.receipt.confirmedAt))+'에 이 파일 묶음의 수령 확인을 남겼습니다.':'아래 파일과 사용 안내를 살펴본 뒤 확인을 남겨 주세요. 확인 시각과 파일 목록이 담당자에게 전달돼요.'}</p></div><ul class="receipt-list">${c.files.map(file=>`<li>${esc(file.label)}</li>`).join('')}</ul>${s.mode==='customer'&&c.canConfirm?btn('파일과 안내 확인했어요','confirm-delivery','','primary'):''}${s.mode==='staff'?'<p class="small">수령 확인은 고객 화면에서 고객이 직접 남깁니다.</p>':''}<p class="small">수령 확인 후에도 자료를 받을 수 있어요. 후속 문의는 05 영상 확인에서 남겨 주세요.</p></section>`}`;}
function historyView(s){const p=s.project,st=studio(p),finals=(p.versions||[]).filter(v=>v.kind==='final'),events=[...(p.messages||[]).map(m=>({at:m.at,title:`${m.authorName} · ${m.action==='approve'?'시안 승인':m.author==='customer'?'고객 의견':'담당자 답변'}`,text:m.text})),...(st.comments||[]).map(m=>({sourceId:'pulse-history-comment-'+m.id,at:m.at,title:`${m.authorName} · ${m.targetType==='concept'?'콘셉트':m.targetType==='scene'?'장면':'프로젝트'} 의견`,text:m.text})),...(st.sceneReviews||[]).map(r=>({sourceId:'pulse-history-review-'+r.id,at:r.at,title:`${r.authorName} · 장면 ${r.status==='confirmed'?'확인':'의견'}`,text:r.text||'장면의 내용과 표현을 확인했어요.'})),...(st.conceptSelections||[st.selectedConcept].filter(Boolean)).map(choice=>({at:choice.at,title:`${choice.authorName} · 콘셉트 선택`,text:((st.concepts||[]).find(c=>c.id===choice.conceptId)?.title||'선택한 방향')+' · v'+choice.conceptRevision})),...(st.cardRevisions||[]).map(card=>({at:card.at,title:`${card.type==='scene'?'장면':'콘셉트'} · 이전 v${card.revision}`,text:card.title+' — '+card.description}))].sort((a,b)=>new Date(b.at)-new Date(a.at));return `${deliveryReceiptView(s)}<section class="section-gap history-files"><div class="block-head"><span class="block-no">01</span><h3>최종 전달 파일</h3></div><div class="delivery-list">${finals.map(v=>`<article class="delivery"><div><span class="tag green">최종 전달</span><h3>${esc(v.label)}</h3><p>${esc(v.guide)}</p></div>${safeUrl(v.media?.url,{media:true})?`<a class="button soft download" href="${esc(safeUrl(v.media.url,{media:true}))}" download>파일 받기</a>`:safeUrl(v.url)?`<a class="button primary" href="${esc(safeUrl(v.url))}" target="_blank" rel="noopener noreferrer">납품 자료 열기 ↗</a>`:''}</article>`).join('')||'<div class="empty-note">최종 파일이 준비되면 사용 안내와 함께 여기로 전달돼요.</div>'}</div></section><div class="button-row section-gap">${btn('후속 문의','tab','data-tab="review" data-scroll="content"','quiet')}</div><section class="section-gap history-records"><div class="block-head"><span class="block-no">02</span><h3>의견과 선택 기록</h3><span class="block-count">${events.length}</span></div><div class="history-list">${events.map(e=>`<article class="history-item"${e.sourceId?` id="${esc(e.sourceId)}" tabindex="-1"`:''}><time>${esc(stamp(e.at))}</time><div><strong>${esc(e.title)}</strong><p>${esc(e.text)}</p></div></article>`).join('')||'<p class="empty-note">함께 나눈 의견과 선택이 여기에 쌓여요.</p>'}</div></section><section class="section-gap history-plan"><div class="block-head"><span class="block-no">03</span><h3>제작 설계 기록</h3></div>${strategyHistory(s.project)||'<p class="empty-note">제작 설계를 저장하면 버전과 확인 기록이 여기에 남아요.</p>'}</section>`;}
function manageView(s){if(s.mode!=='staff')return '';const p=s.project;return `<div class="settings-grid"><form class="panel-card" data-form="project"><fieldset ${!s.canEdit?'disabled':''}>${field('프로젝트 이름','title',p.title,'text',{required:true,max:160})}${field('고객 이름','customerName',p.customerName,'text',{required:true,max:100})}<label class="field">현재 단계<select name="stage">${Object.entries(stages).map(([key,label])=>`<option value="${key}" ${p.stage===key?'selected':''}>${label}</option>`).join('')}</select></label>${field('합의한 전달 예정일','dueDate',p.dueDate||'','date')}${field('고객이 지금 확인할 일','nextStep',p.nextStep||'','textarea',{max:600})}${field('함께 만들 내용','summary',p.summary||'','textarea')}${field('제작 범위·수정 조건','terms',p.terms||'','textarea')}${s.canEdit?submit('프로젝트 저장'):''}</fieldset></form><div class="stack"><section class="panel-card invite-box"><h3>고객 초대</h3><p class="small">초대 링크로 이 프로젝트만 열 수 있어요. 새 초대를 만들면 이전 접근은 끝나요.</p>${s.canEdit?btn('새 고객 초대 만들기','invite','','primary'):''}${s.inviteUrl?`${field('직접 전달할 고객 링크','invite-url',s.inviteUrl,'text',{max:3000})}<div class="button-row">${btn('초대 링크 복사','copy-invite')}<a class="button" href="${esc(s.inviteUrl)}" target="_blank" rel="noopener noreferrer">고객 화면 열기 ↗</a></div><p class="small">자동 발송되지 않아요. 고객에게 직접 전달해 주세요.</p>`:''}${s.canEdit?`<hr class="divider">${btn('고객 접근 종료','revoke','','quiet danger')}`:''}</section><section class="panel-card"><h3>최신 내용 확인</h3><p class="small">고객이 남긴 선택과 의견은 자동으로 반영돼요. 작성 중에는 글과 파일을 보존하고, 입력을 마치면 새 내용을 표시해요.</p>${btn('새로 불러오기','refresh')}</section></div></div>`;}
export function dialogContent(type,item={}){
  if(type==='install'){const guide=item.guide;return `<span class="eyebrow">PULSE ON YOUR DEVICE</span><h2 id="dialog-title">${esc(guide.title)}</h2>${item.installed?'<p class="install-success">설치했어요. 홈 화면의 PULSE를 열어 기기 알림을 켜 주세요.</p>':''}<p>${esc(guide.summary)}</p><ol class="install-steps">${guide.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="install-notes">${guide.notes.map(note=>`<p class="small">${esc(note)}</p>`).join('')}</div><div class="button-row">${guide.canPrompt?btn('이 기기에 설치','install-now','','primary'):''}${guide.openNotifications?btn('기기 알림 설정','install-notifications','','primary'):''}${btn('닫기','close-dialog')}</div>`;}
  if(type==='delivery-confirm')return `<span class="eyebrow">DELIVERY RECEIPT</span><h2 id="dialog-title">이 파일과 안내를 확인했나요?</h2><div class="receipt-files">${item.files.map(file=>`<article><strong>${esc(file.label)}</strong><p>${esc(file.guide||'')}</p></article>`).join('')}</div><form data-form="confirm-delivery" data-id="${esc(item.deliveryKey)}" data-revision="${esc(item.revision)}"><label class="receipt-check"><input type="checkbox" name="confirmed" value="yes" required>위 전달 파일을 열어 보고 사용 안내를 확인했습니다.</label><p class="small">확인한 파일 목록과 시각이 기록돼요. 이후에도 자료를 내려받거나 문의할 수 있어요.</p><div class="button-row">${btn('다시 살펴보기','close-dialog')}${submit('수령 확인 남기기')}</div></form>`;
  if(type==='strategy-confirm')return strategyConfirmDialog(item);
  if(type==='image')return `<button class="dialog-close" type="button" data-action="close-dialog" aria-label="이미지 닫기">×</button><img src="${esc(item.src)}" alt="${esc(item.label)}" referrerpolicy="${new URL(item.src,location.origin).origin!==location.origin?'origin':'no-referrer'}"><h2 id="dialog-title">${esc(item.label)}</h2>`;
  if(type==='reference')return `<span class="eyebrow">REFERENCE PREFERENCE</span><h2 id="dialog-title">${esc(item.label)}</h2><form data-form="reference-opinion" data-id="${esc(item.id)}"><label class="field">이 자료에 대한 생각<select name="preference"><option value="like" ${item.preference==='like'?'selected':''}>이런 느낌이 좋아요</option><option value="avoid" ${item.preference==='avoid'?'selected':''}>이런 느낌은 피하고 싶어요</option><option value="neutral" ${item.preference==='neutral'?'selected':''}>참고만 해 주세요</option></select></label>${field('어떤 부분인가요?','reason',item.reason||'','textarea')}<div class="button-row">${btn('닫기','close-dialog')}${submit('내 생각 저장')}</div></form>`;
  if(type==='choose')return `<span class="eyebrow">CREATIVE DIRECTION</span><h2 id="dialog-title">이 방향으로 함께 만들까요?</h2><div class="version-name">${esc(item.title)} · v${esc(item.revision)}</div><form data-form="select-concept" data-id="${esc(item.id)}" data-revision="${esc(item.revision)}">${field('특히 마음에 드는 점·보완할 점','text','','textarea',{placeholder:'선택한 이유를 알려 주면 장면에 반영할 수 있어요.'})}<div class="button-row">${btn('다시 비교하기','close-dialog')}${submit('이 콘셉트 선택')}</div></form>`;
  if(type==='scene')return `<span class="eyebrow">SCENE FEEDBACK</span><h2 id="dialog-title">${esc(item.title)}</h2><form data-form="review-scene" data-id="${esc(item.id)}" data-revision="${esc(item.revision)}"><label class="field">의견 종류<select name="status"><option value="changes">바꾸고 싶은 부분이 있어요</option><option value="comment">참고할 의견이에요</option></select></label>${field('어떤 부분인가요?','text','','textarea',{required:true,placeholder:'바뀌면 좋을 부분과 이유를 알려 주세요.'})}<div class="button-row">${btn('닫기','close-dialog')}${submit('이 장면에 의견 남기기')}</div></form>`;
  if(type==='comment')return `<span class="eyebrow">LET’S TALK</span><h2 id="dialog-title">${esc(item.title)}</h2><form data-form="comment" data-id="${esc(item.id)}" data-target="${esc(item.type)}" data-revision="${esc(item.revision)}">${field('남길 의견','text','','textarea',{required:true,placeholder:'이 자료에 관해 함께 확인할 내용을 적어 주세요.'})}<div class="button-row">${btn('닫기','close-dialog')}${submit('의견 보내기')}</div></form>`;
  if(type==='approve')return `<span class="eyebrow">FINAL PREVIEW APPROVAL</span><h2 id="dialog-title">이 시안을 승인할까요?</h2><div class="version-name">${esc(item.label)}</div><p>내용과 표현을 확인했으며, 이 버전을 기준으로 최종 제작을 진행하는 데 동의합니다. 승인 버전과 시각이 기록됩니다.</p><div class="button-row">${btn('다시 살펴보기','close-dialog')}${btn('확인했고 승인합니다','approve-confirm',`data-id="${esc(item.id)}" data-revision="${esc(item.revision)}" data-mutate`,'primary')}</div>`;
  if(type==='leave')return `<h2 id="dialog-title">작성 중인 내용이 있어요.</h2><p>아직 보내지 않은 내용이 있어요. 화면을 떠나면 작성 중인 글과 선택한 파일은 사라집니다.</p><div class="button-row">${btn('돌아가서 계속 쓰기','leave-cancel')}${btn('작성 내용 버리고 이동','leave-confirm','','primary')}</div>`;
  if(type==='confirm')return `<h2 id="dialog-title">${esc(item.title)}</h2><p>${esc(item.text)}</p><div class="button-row">${btn('취소','close-dialog')}${btn(item.button||'확인','confirm-action','data-mutate','primary')}</div>`;
  return '';
}

export function liveView(s){const live=s.live||{},labels={connecting:'자동 연결 중',connected:'실시간 반영 중',reconnecting:'다시 연결하는 중',offline:'오프라인 · 연결되면 반영'},items=live.notifications||[];return `<div class="live-status is-${esc(live.status||'connecting')}" role="status"><span class="live-dot ${esc(live.status)}" aria-hidden="true"></span><span class="live-label">${esc(labels[live.status]||labels.connecting)}</span>${live.pending?'<span class="live-pending">새 내용이 도착했어요. 쓰던 글과 대화상자를 마치면 반영돼요.</span>':''}</div>${live.open?`<section id="pulse-notifications" class="notification-panel" aria-label="PULSE 알림함"><header><h2 tabindex="-1">알림 <span>${esc(live.unreadCount||0)}</span></h2>${btn('닫기','close-notifications','','quiet small-button')}</header><p class="small">${s.mode==='staff'?'고객의 의견과 승인, 새 요청을 확인하세요.':'제작팀의 확인 요청과 답변, 새 자료를 확인하세요.'}</p><div class="notification-tools">${btn('모두 읽음','read-notifications',!live.unreadCount?'disabled':'','quiet small-button')}${btn(live.deviceBusy?'설정 중…':live.deviceEnabled?'기기 알림 끄기':'기기 알림 켜기','device-notifications',!live.deviceReady||live.deviceBusy?'disabled':'','quiet small-button')}${btn(s.mode==='staff'?'로그아웃':'연결 닫기','logout','','quiet small-button panel-logout')}</div><p class="notification-help">${esc(live.deviceProgress||live.deviceNote||'기기 알림 상태를 확인하고 있어요.')}</p>${live.deviceIssue?`<p class="notification-help" role="status">${esc(live.deviceIssue)}</p>`:''}<div class="notification-list">${items.map(item=>`<button type="button" class="notification-item ${item.unread?'unread':''}" data-action="open-notification" data-id="${esc(item.id)}"><span class="notification-item-top">${item.unread?'<span class="notification-unread">새 소식</span>':'<span class="small">확인함</span>'}<time>${esc(stamp(item.createdAt))}</time></span>${item.projectTitle?`<span class="notification-project">${esc(item.projectTitle)}</span>`:''}<strong>${esc(item.title)}</strong><span>${esc(item.body||'관련 내용을 확인해 주세요.')}</span></button>`).join('')||'<p class="empty-note">아직 새 알림이 없어요.<br>상대방이 의견이나 새 자료를 남기면 알려 드릴게요.</p>'}</div></section>`:''}`;}

function demoGuide(s){const g=s.demoGuide;return `<section class="demo-guide" data-demo-guide data-demo-action="${esc(g.action)}" aria-label="고객 체험 안내"><div class="demo-guide-copy"><div class="demo-guide-top"><span class="tag berry">체험 프로젝트</span><span class="demo-step">${esc(g.step)} / ${esc(g.total)}</span><span class="small">모루 15초 광고</span></div><h2>${esc(g.title)}</h2><p>${esc(g.description)}</p><p class="demo-storage-note">${s.demoPersistent?'선택·의견은 이 브라우저에만 저장돼요.':'이 브라우저에서 저장을 사용할 수 없어 창을 닫으면 체험 기록이 사라집니다.'} 실제 의뢰·기획 확인·승인으로 전송되지 않아요. 영상과 수정본은 미리 준비한 예시예요.</p></div><div class="demo-guide-actions">${g.complete?btn('처음부터 다시 체험','demo-reset','','primary'):btn(g.canAdvance?g.button:'이 단계 체험하기 →','demo-next','','primary')}<span class="small">로그인 없이 자유롭게 체험하세요.</span></div></section>`;}
